window.SP_DATA=window.SP_DATA||{subjects:{}};SP_DATA.subjects["sem2_contract2"]={"chapters":{},"glossary":[{"term_en":"(comparative questions) |  \n|","term_te":"","definition_en":"Comparative questions are inquiries that ask for comparisons between two or more legal concepts, statutes, cases, or jurisdictions.","definition_te":"","example":"\"How does the criminal liability of an accomplice differ from that of a principal in Indian law?\""},{"term_en":"(core concept) |  \n|","term_te":"","definition_en":"A fundamental principle or idea that forms the basis of a legal rule, doctrine, or system.","definition_te":"","example":"The core concept of \"due process\" ensures fair treatment through lawful procedures in judicial matters."},{"term_en":"(mandatory roles) |  \n|","term_te":"","definition_en":"Mandatory roles are positions or responsibilities that individuals must fulfill by legal requirement.","definition_te":"","example":"A judge's role in presiding over court proceedings is mandatory."},{"term_en":"(procedural steps) |  \n\n---\n\n###","term_te":"","definition_en":"Procedural steps are the specific actions or processes that must be followed in legal proceedings to ensure fairness and compliance with laws.","definition_te":"","example":"Filing a complaint, serving notice, and appearing before a court are procedural steps in initiating a lawsuit."},{"term_en":"(procedure) |  \n|","term_te":"","definition_en":"A set of rules and steps followed in legal processes to ensure fairness and order.","definition_te":"","example":"The procedure for filing a lawsuit includes submitting a complaint, serving the defendant, and attending court hearings."},{"term_en":"(registration process) |  \n|","term_te":"","definition_en":"The registration process refers to the formal procedure of recording legal documents or entities with an official authority.","definition_te":"","example":"Registering a company with the Registrar of Companies."},{"term_en":"(section 14).","term_te":"","definition_en":"Section 14 of the Indian Evidence Act, 1872 deals with the relevancy of facts that show the existence or non-existence of a state of mind.","definition_te":"","example":"A statement made by an accused showing their intention to commit a crime is relevant under this section."},{"term_en":"(section 14).  \n-","term_te":"","definition_en":"Section 14 of the Indian Evidence Act deals with the relevancy of facts showing existence or non-existence of state of mind.","definition_te":"","example":"A witness testifying about a person's fear before an event to prove their mental condition at that time."},{"term_en":".  \n\n---\n\n###","term_te":"","definition_en":"A legal term referring to the formal statement of charges brought against an accused person in criminal proceedings.","definition_te":"","example":"An indictment for murder filed by the prosecution against a defendant."},{"term_en":".  \n- common in","term_te":"","definition_en":"A term used to describe something that is frequently encountered or widespread.","definition_te":"","example":"The phrase \"common in criminal cases\" refers to evidence that is often found in such proceedings."},{"term_en":".  \n- high-frequency for","term_te":"","definition_en":"High-frequency trading refers to the use of sophisticated algorithms and powerful computers to execute trades at extremely high speeds.","definition_te":"","example":"A firm uses automated systems to trade stock options within milliseconds based on market data changes."},{"term_en":"2(26)","term_te":"","definition_en":"2(26) refers to the definition of 'person' under Section 2(26) of the Indian Penal Code, which includes any person who is not a company.","definition_te":"","example":"A shopkeeper committing theft would be considered as a \"person\" under this section."},{"term_en":"212–218","term_te":"","definition_en":"Sections 212-218 of the Indian Penal Code deal with offenses related to false evidence and giving false testimony in legal proceedings.","definition_te":"","example":"A witness lying under oath during a trial can be charged under these sections."},{"term_en":":  \n- section 14.","term_te":"","definition_en":"Section 14 of the Indian Penal Code deals with acts done by one person, which are intended to cause harm to another.","definition_te":"","example":"If A throws a stone at B intending to injure him, it falls under section 14."},{"term_en":": distinguished between","term_te":"","definition_en":"To make clear differences or distinctions between things.","definition_te":"","example":"The court distinguished between murder and manslaughter based on intent."},{"term_en":": goods must be","term_te":"","definition_en":"Goods must be refers to the requirement that items involved in a contract of sale should be physically movable and not attached to land.","definition_te":"","example":"A car sold under a sales agreement is an example of goods that must be moved from one place to another."},{"term_en":": seller must have","term_te":"","definition_en":"The seller is required to possess the goods at the time of sale.","definition_te":"","example":"A car dealer must own the vehicle before selling it to a customer."},{"term_en":"a) partnership structure","term_te":"","definition_en":"A partnership structure is a business arrangement where two or more individuals jointly own and operate a company.","definition_te":"","example":"Two lawyers starting a firm together, sharing profits and liabilities equally."},{"term_en":"accounting","term_te":"","definition_en":"Accounting is the process of recording, summarizing, and reporting financial transactions to provide accurate information about an organization's economic activities.","definition_te":"","example":"A company prepares its annual profit and loss statement using accounting principles."},{"term_en":"act in good faith","term_te":"","definition_en":"Acting honestly and with proper intentions without any deceit or malice.","definition_te":"","example":"A buyer purchasing property after verifying all legal documents thoroughly."},{"term_en":"agency by necessity","term_te":"","definition_en":"Agency by necessity arises when an agent acts on behalf of another person to prevent significant loss or harm in an emergency situation.","definition_te":"","example":"A shopkeeper selling goods from a store to pay for urgent medical expenses of the owner."},{"term_en":"agency in partnership","term_te":"","definition_en":"Agency in partnership refers to the authority of one partner to act on behalf of the firm and bind other partners.","definition_te":"","example":"If A is a partner in a business, he can enter into contracts for the firm without needing consent from all other partners."},{"term_en":"agent vs. servant","term_te":"","definition_en":"An agent acts on behalf of another with authority to bind them, while a servant is employed to perform tasks under the employer's control.","definition_te":"","example":"A real estate broker is an agent, whereas a company employee following direct orders is a servant."},{"term_en":"agreement","term_te":"","definition_en":"An agreement is a mutual understanding between two or more parties regarding the terms of their relationship.","definition_te":"","example":"A contract between a buyer and seller for the purchase of goods."},{"term_en":"agreement to sell","term_te":"","definition_en":"An agreement to sell is a contract where the seller agrees to transfer ownership of goods to the buyer at a future date upon fulfillment of certain conditions.","definition_te":"","example":"A farmer agreeing to sell his harvest to a trader after it has been harvested and weighed."},{"term_en":"apparent authority","term_te":"","definition_en":"Apparent authority refers to the power that an agent appears to have based on representations made by their principal.","definition_te":"","example":"A manager hired by a company may appear to have the authority to sign contracts on behalf of the business, even if they were not actually authorized."},{"term_en":"apparent authority and estoppel","term_te":"","definition_en":"Apparent authority is when third parties reasonably believe an agent has the power to act on behalf of a principal, and estoppel prevents the principal from denying this belief if it caused reliance.","definition_te":"","example":"A manager signs a contract for their employer without proper authorization; the employer cannot later deny the agreement if the other party relied on the manager's apparent authority."},{"term_en":"application in real-life scenarios","term_te":"","definition_en":"Application in real-life scenarios refers to the practical use of legal principles and rules in actual situations.","definition_te":"","example":"Using contract laws to resolve a dispute between two business partners over breached terms."},{"term_en":"as an implied condition.","term_te":"","definition_en":"An implied condition is a term that must be fulfilled in order to make the contract valid, even though it was not explicitly stated.","definition_te":"","example":"In a sale of land, an implied condition may require the seller to have clear title to the property."},{"term_en":"as high-yield topics.  \n\n---","term_te":"","definition_en":"High-yield topics are areas of study that frequently appear in legal exams and carry significant weightage.","definition_te":"","example":"Contract Law is often considered a high-yield topic for LL.B. students preparing for the Bar Examination."},{"term_en":"ascertained","term_te":"","definition_en":"Ascertained refers to something that has been clearly identified or determined.","definition_te":"","example":"The court ascERTAINED the ownership of the property through documentary evidence."},{"term_en":"ascertained goods","term_te":"","definition_en":"Ascertained goods are specific items that have been identified and separated from the general mass of similar goods.","definition_te":"","example":"A particular car specified by make, model, and registration number."},{"term_en":"aspect","term_te":"","definition_en":"An aspect refers to a particular feature or element of a legal issue that is considered in analysis.","definition_te":"","example":"In criminal law, the intent aspect determines whether an act was premeditated."},{"term_en":"authority","term_te":"","definition_en":"Authority refers to the power or right to make decisions and enforce obedience within a legal system.","definition_te":"","example":"A judge has authority to interpret laws and pass judgments in court cases."},{"term_en":"b) liability of partners","term_te":"","definition_en":"Liability of partners refers to the legal responsibility each partner has towards the debts and obligations of the partnership.","definition_te":"","example":"If a partnership owes money, all partners are personally liable for repaying it."},{"term_en":"bailee’s duties","term_te":"","definition_en":"A bailee's duties include taking reasonable care of the bailed property and using it only in accordance with the bailor’s instructions.","definition_te":"","example":"If someone lends their car to a friend, the friend must drive carefully and not use it for illegal activities."},{"term_en":"bailee’s rights","term_te":"","definition_en":"A bailee's rights refer to the legal entitlements of a person who temporarily holds possession of another's property under an agreement.","definition_te":"","example":"A hotel guest has the right to use their luggage stored in the locker without interference from the hotel staff."},{"term_en":"bailment","term_te":"","definition_en":"Bailment is the transfer of possession of goods from one person to another for a specific purpose, with an agreement that they will be returned or disposed of according to certain conditions.","definition_te":"","example":"Lending your car to a friend for a day with the understanding it will be returned intact."},{"term_en":"bailor’s duties","term_te":"","definition_en":"A bailor's duties include taking reasonable care of the bailed goods and not using them in ways that could damage or devalue them.","definition_te":"","example":"If someone lends their car for a trip, they must ensure it is properly maintained before handing it over."},{"term_en":"bailor’s rights","term_te":"","definition_en":"Bailor's rights refer to the legal entitlements of a person who entrusts their property to another for use or storage.","definition_te":"","example":"A bailor can demand return of their goods if the bailee fails to fulfill obligations under the bailment agreement."},{"term_en":"bhide v. m/s. sahu (1974)","term_te":"","definition_en":"The case Bhide v. M/S Sahu (1974) is related to the interpretation of contract terms and conditions in Indian law.","definition_te":"","example":"It clarified that ambiguous clauses in a lease agreement should be interpreted against the party who drafted them."},{"term_en":"breach of condition","term_te":"","definition_en":"A breach of condition occurs when one party fails to perform a fundamental term of the contract, which may allow the other party to terminate the agreement.","definition_te":"","example":"Failing to deliver goods as agreed in a sales contract."},{"term_en":"breach of warranty","term_te":"","definition_en":"A breach of warranty occurs when one party fails to meet the terms specified in a contract's warranty.","definition_te":"","example":"Selling used car without disclosing prior accident history."},{"term_en":"business","term_te":"","definition_en":"Business refers to the organized activity of producing, buying, and selling goods or services with the aim of making profit.","definition_te":"","example":"A company manufacturing smartphones for sale is an example of a business."},{"term_en":"buyer","term_te":"","definition_en":"A buyer is a person who purchases goods or services from another party in a transaction.","definition_te":"","example":"John bought a car from Sarah for $20,000."},{"term_en":"by third parties.  \n-","term_te":"","definition_en":"Actions or statements made by individuals not directly involved in the legal matter at hand.","definition_te":"","example":"A witness testifying about events they observed during a crime."},{"term_en":"c) registration","term_te":"","definition_en":"Registration refers to the formal process of recording legal documents or actions with an official authority.","definition_te":"","example":"Registering a property deed with the local land registry office."},{"term_en":"case expected","term_te":"","definition_en":"A case that is anticipated or likely to occur based on previous patterns or legal precedents.","definition_te":"","example":"The court may refer to past rulings when considering a \"case expected\" in contract law disputes."},{"term_en":"cases listed","term_te":"","definition_en":"Cases listed refer to the compilation of judicial decisions that are cited or referenced in legal proceedings.","definition_te":"","example":"A list of cases from previous court rulings used to support an argument in a current trial."},{"term_en":"company","term_te":"","definition_en":"A company is an artificial person created by law with a separate legal entity distinct from its shareholders.","definition_te":"","example":"Reliance Industries Limited is a well-known Indian public limited company."},{"term_en":"comparative questions","term_te":"","definition_en":"Comparative questions are inquiries that ask students to compare and contrast legal concepts, principles, or cases.","definition_te":"","example":"\"Compare the elements of criminal negligence with those of intentional homicide.\""},{"term_en":"comparison: bailment vs. pledge","term_te":"","definition_en":"Bailment involves temporary transfer of possession, while pledge is a type of bailment where goods are given as security for a debt.","definition_te":"","example":"A pawnshop receiving jewelry as collateral is a pledge; lending a friend your bike to use temporarily is a bailment."},{"term_en":"compulsory","term_te":"","definition_en":"Compulsory refers to something that is legally required or mandated.","definition_te":"","example":"Attendance at school is compulsory in most jurisdictions until the age of 16."},{"term_en":"condition","term_te":"","definition_en":"A condition is a term in a contract that imposes an obligation or sets circumstances under which a party's rights and duties arise.","definition_te":"","example":"Payment of rent is conditional upon the tenant maintaining the property in good repair."},{"term_en":"conditions for termination","term_te":"","definition_en":"Conditions for termination refer to the specific circumstances under which a contract or employment relationship can legally end.","definition_te":"","example":"An employee's job may be terminated if they consistently fail to meet performance standards as outlined in their contract."},{"term_en":"conditions vs warranties","term_te":"","definition_en":"Conditions are essential terms of a contract, while warranties are less critical and relate to the quality or performance of goods.","definition_te":"","example":"A condition might be delivery by a certain date, whereas a warranty could guarantee product functionality."},{"term_en":"contract","term_te":"","definition_en":"A contract is a legally enforceable agreement between two or more parties involving an offer, acceptance, and consideration.","definition_te":"","example":"When someone buys a book from a shopkeeper for ₹100, it forms a simple contractual relationship."},{"term_en":"contract of sale","term_te":"","definition_en":"A contract of sale is an agreement where one party agrees to sell and the other agrees to buy goods.","definition_te":"","example":"When John sells his car to Mary for ₹50,000, a contract of sale is formed between them."},{"term_en":"creation of agency","term_te":"","definition_en":"The formation of an agent relationship through express agreement, implied conduct, or necessity.","definition_te":"","example":"A person appoints another to sell their car on their behalf."},{"term_en":"cundy v. lindsay (1874)","term_te":"","definition_en":"Cundy v Lindsay (1874) is a case where the court held that an agent's apparent authority can bind the principal even if there was no actual authorization.","definition_te":"","example":"A shopkeeper allows someone to act as his salesperson, and customers reasonably believe they have authority to make purchases on behalf of the shop."},{"term_en":"d) management","term_te":"","definition_en":"Management refers to the process of organizing and coordinating activities to achieve organizational goals efficiently.","definition_te":"","example":"A company's board of directors managing its operations and strategic direction."},{"term_en":"defects","term_te":"","definition_en":"Defects refer to flaws or imperfections in goods, contracts, or legal documents that may affect their value, usability, or validity.","definition_te":"","example":"A defect in a contract could be an ambiguous clause that leads to disputes between the parties involved."},{"term_en":"definition of agency","term_te":"","definition_en":"Agency is the legal relationship where one person (agent) acts on behalf of another (principal) with their authority.","definition_te":"","example":"A real estate agent signing a contract for sale on behalf of their client."},{"term_en":"definition of partnership","term_te":"","definition_en":"A partnership is an association of two or more persons who agree to carry on a business and share its profits and losses.","definition_te":"","example":"Two friends starting a retail store together and splitting the earnings equally."},{"term_en":"delivery","term_te":"","definition_en":"Delivery refers to the act of transferring possession or ownership of property from one person to another.","definition_te":"","example":"Handing over keys to a house upon completion of a sale contract."},{"term_en":"delivery of goods","term_te":"","definition_en":"Delivery of goods refers to the transfer of possession from the seller to the buyer under a contract of sale.","definition_te":"","example":"A shopkeeper handing over a purchased television to a customer."},{"term_en":"delivery vs passing of property","term_te":"","definition_en":"Delivery refers to the physical transfer of goods, while passing of property denotes the legal ownership transfer.","definition_te":"","example":"Handing over a car key is delivery; registration in the buyer's name is passing of property."},{"term_en":"description","term_te":"","definition_en":"A description is a detailed account or characterization of something to identify it clearly.","definition_te":"","example":"Describing the suspect's clothing and vehicle in a police report."},{"term_en":"designated partners","term_te":"","definition_en":"Designated partners are specific individuals in certain partnerships who have special rights or responsibilities under the partnership agreement.","definition_te":"","example":"In a limited liability partnership, designated partners may be responsible for managing business operations."},{"term_en":"difference between bailment and pledge","term_te":"","definition_en":"Bailment is the transfer of goods for a specific purpose, while pledge involves transferring possession of property as security for a debt.","definition_te":"","example":"A shopkeeper keeping customer's bag safely is bailment; lending jewelry to secure a loan is a pledge."},{"term_en":"difference between pledge and mortgage","term_te":"","definition_en":"A pledge involves the delivery of goods as security, while a mortgage is a charge on immovable property without transferring possession.","definition_te":"","example":"Pledging jewelry to borrow money vs. mortgaging land for a loan."},{"term_en":"dissolution","term_te":"","definition_en":"Dissolution refers to the legal process of ending a partnership or company by winding up its affairs and distributing assets.","definition_te":"","example":"A partnership may be dissolved if all partners agree to terminate their business operations."},{"term_en":"dissolution by agreement","term_te":"","definition_en":"Dissolution by agreement refers to the mutual consent of partners in a firm to terminate their partnership.","definition_te":"","example":"All partners agree to dissolve the business and settle accounts within three months."},{"term_en":"dissolution by expulsion","term_te":"","definition_en":"Dissolution by expulsion refers to the termination of a partnership when one or more partners are expelled due to misconduct, breach of agreement, or other valid reasons.","definition_te":"","example":"A partner is forcibly removed from a firm for embezzling funds."},{"term_en":"dissolution by retirement","term_te":"","definition_en":"Dissolution by retirement refers to the termination of a partnership when one or more partners retire from the business.","definition_te":"","example":"A partner retires, leading to the dissolution of the firm unless otherwise agreed upon by remaining partners."},{"term_en":"dissolution of partnership","term_te":"","definition_en":"Dissolution of partnership refers to the termination of an existing partnership and its business operations.","definition_te":"","example":"When all partners agree to end their joint venture due to financial losses."},{"term_en":"distinct entity","term_te":"","definition_en":"A distinct entity is an organization or legal person that exists separately from its owners or members.","definition_te":"","example":"A company incorporated under the Companies Act is a distinct entity separate from its shareholders."},{"term_en":"distinguishing","term_te":"","definition_en":"Distinguishing is the process of identifying differences between legal cases to determine whether a previous decision applies to the current case.","definition_te":"","example":"A court may distinguish a prior ruling on contract law by noting that the present case involves an oral agreement, whereas the earlier one involved a written contract."},{"term_en":"does not transfer property.","term_te":"","definition_en":"A term indicating that ownership or rights in property are not passed from one party to another.","definition_te":"","example":"When a lease is granted, it does not transfer property ownership to the tenant."},{"term_en":"duties","term_te":"","definition_en":"Duties are legal or moral obligations that individuals must fulfill towards others.","definition_te":"","example":"A citizen's duty to obey laws and pay taxes."},{"term_en":"duties of agents","term_te":"","definition_en":"Agents have a duty to act in the best interests of their principal and perform tasks with care, loyalty, and honesty.","definition_te":"","example":"An agent must not disclose confidential information about their client to third parties."},{"term_en":"duties of principals","term_te":"","definition_en":"Duties of principals include ensuring the safety and well-being of their agents while they carry out tasks on behalf of the principal.","definition_te":"","example":"A business owner must provide proper training to employees handling sensitive data."},{"term_en":"duty to use skills","term_te":"","definition_en":"A legal obligation requiring individuals or professionals to apply their knowledge and abilities competently in performing tasks.","definition_te":"","example":"A lawyer must use their skills diligently when representing a client in court."},{"term_en":"essential elements of bailment","term_te":"","definition_en":"Bailment involves the transfer of possession of goods from one person to another for a specific purpose.","definition_te":"","example":"Lending your bike to a friend to go shopping and agreeing to return it later."},{"term_en":"essential elements of partnership","term_te":"","definition_en":"A partnership requires an agreement between two or more people to share profits and losses from a business.","definition_te":"","example":"Two friends starting a bakery together, splitting both expenses and earnings."},{"term_en":"essential elements of pledge","term_te":"","definition_en":"A pledge involves the transfer of possession of movable property by a debtor to a creditor as security for repayment of debt.","definition_te":"","example":"Pledging jewelry with a bank as collateral for a loan."},{"term_en":"estoppel","term_te":"","definition_en":"Estoppel is a legal principle that prevents someone from denying or acting contrary to a fact already established by their previous actions or statements.","definition_te":"","example":"If A falsely tells B they have the right to use land, and B relies on this statement to build a house, A may be estopped from later claiming ownership of the land."},{"term_en":"exceptions","term_te":"","definition_en":"Exceptions are provisions in laws that exclude certain situations from the general application of a rule.","definition_te":"","example":"The Indian Penal Code excludes acts done by a person under unsoundness of mind from criminal liability."},{"term_en":"express agency","term_te":"","definition_en":"An express agency is formed when the principal explicitly authorizes an agent to act on their behalf.","definition_te":"","example":"A business owner signs a contract with another party, clearly stating that their employee has authority to negotiate deals."},{"term_en":"fisons v. little (1956)","term_te":"","definition_en":"Fison v. Little (1956) is a UK case that established the principle of vicarious liability in cases involving psychiatric injury caused by witnessing criminal acts.","definition_te":"","example":"A bystander who suffers mental harm from watching an assault may claim compensation if the employer of the assailant is held liable."},{"term_en":"fit for a particular purpose","term_te":"","definition_en":"A term in contract law indicating that goods sold must meet the specific needs or requirements of the buyer.","definition_te":"","example":"Selling a laptop guaranteed to run graphic design software without issues."},{"term_en":"fit for purpose","term_te":"","definition_en":"A term used in contract law to describe goods or services that meet the specific requirements agreed upon by the parties.","definition_te":"","example":"If a contractor builds a house according to the client's specifications, it is considered \"fit for purpose.\""},{"term_en":"fitness for purpose","term_te":"","definition_en":"Fitness for purpose refers to the requirement that goods or services must be suitable for their intended use.","definition_te":"","example":"A manufacturer of safety helmets is liable if the helmet fails to protect against head injuries as expected."},{"term_en":"flexibility","term_te":"","definition_en":"Flexibility in legal terms refers to the ability of laws or judicial decisions to adapt to changing circumstances.","definition_te":"","example":"A court may apply a flexible interpretation of a statute to address new technological challenges."},{"term_en":"flexible profit-sharing","term_te":"","definition_en":"Flexible profit-sharing refers to an arrangement where employees receive a portion of company profits, with the percentage or conditions subject to change based on performance or agreement.","definition_te":"","example":"A firm may distribute 10% of annual profits to employees if targets are met, adjusting this share annually depending on financial results."},{"term_en":"fraudulent acts","term_te":"","definition_en":"Fraudulent acts are intentional deceptions committed to gain an unfair advantage or cause harm.","definition_te":"","example":"Falsifying documents to secure a loan."},{"term_en":"frequently asked topics","term_te":"","definition_en":"Topics that are commonly inquired about or discussed within the legal field.","definition_te":"","example":"Legal procedures for filing a lawsuit."},{"term_en":"general agent","term_te":"","definition_en":"A general agent is an individual authorized to act on behalf of another person in all matters relating to a particular business or transaction.","definition_te":"","example":"A managing director acting for a company in all its operations."},{"term_en":"general partnership","term_te":"","definition_en":"A general partnership is an association of two or more persons who carry on a business together and are jointly liable for the debts and obligations of the partnership.","definition_te":"","example":"Two friends starting a small retail store, each contributing capital and sharing profits and losses equally."},{"term_en":"general vs. special agent","term_te":"","definition_en":"A general agent has broad authority to act on behalf of the principal in all matters, while a special agent is limited to specific tasks or transactions.","definition_te":"","example":"A real estate broker is a special agent, whereas a company's CEO is generally considered a general agent."},{"term_en":"good title","term_te":"","definition_en":"A good title refers to the legal right of ownership that is clear, valid, and free from any disputes or encumbrances.","definition_te":"","example":"When a seller transfers property with no liens or claims against it, they have a good title."},{"term_en":"goods","term_te":"","definition_en":"Goods refer to movable property that can be bought and sold.","definition_te":"","example":"A television set is an example of goods."},{"term_en":"gratuitous bailment","term_te":"","definition_en":"A gratuitous bailment is a type of bailment where the bailee does not receive any compensation or benefit from the bailor.","definition_te":"","example":"Lending your friend a book without expecting anything in return."},{"term_en":"guarantee","term_te":"","definition_en":"A guarantee is a promise by one party to be responsible for the performance of another party's obligation.","definition_te":"","example":"If X guarantees Y’s loan, X agrees to repay it if Y fails to do so."},{"term_en":"high","term_te":"","definition_en":"High refers to the state of being elevated in position or rank.","definition_te":"","example":"The high court has authority over lower courts."},{"term_en":"implied agency","term_te":"","definition_en":"Implied agency refers to an agency relationship that arises from the conduct of parties rather than explicit agreement.","definition_te":"","example":"A shopkeeper allowing a salesperson to manage daily operations implies authority to make routine decisions."},{"term_en":"implied by law","term_te":"","definition_en":"An obligation or right that is created by operation of law rather than by the express agreement of parties.","definition_te":"","example":"A landlord's duty to maintain a habitable living condition for tenants under implied warranty of habitation."},{"term_en":"implied terms","term_te":"","definition_en":"Implied terms are conditions that are not explicitly stated in a contract but are inferred by the court to be part of the agreement based on context, custom, or law.","definition_te":"","example":"A duty of care implied between landlord and tenant under lease agreements."},{"term_en":"implied warranty of title","term_te":"","definition_en":"An implied warranty that the seller has clear and marketable title to the goods sold.","definition_te":"","example":"If a car dealer sells a vehicle without disclosing prior liens, they breach this warranty."},{"term_en":"indemnification","term_te":"","definition_en":"Indemnification is the legal obligation to compensate another party for losses or damages incurred.","definition_te":"","example":"A manufacturer may indemnify a retailer against claims arising from defective products sold by the retailer."},{"term_en":"indian partnership act, 1932","term_te":"","definition_en":"The Indian Partnership Act, 1932 is the legislation that governs partnerships in India by defining their formation, rights and duties of partners.","definition_te":"","example":"A partnership between two individuals running a retail store together under a common name."},{"term_en":"ingratuitous bailment","term_te":"","definition_en":"An ingratuitous bailment is a type of bailment where the bailee does not receive any compensation or benefit from the bailor.","definition_te":"","example":"Lending your friend a book without expecting anything in return."},{"term_en":"invalidity of llp","term_te":"","definition_en":"Invalidity of LLP occurs when the partnership fails to meet legal requirements, rendering it legally non-existent.","definition_te":"","example":"Failure to file required documents with the Registrar of Companies within stipulated time."},{"term_en":"key concept","term_te":"","definition_en":"A key concept is a fundamental idea or principle that forms the basis of understanding legal rules and doctrines.","definition_te":"","example":"The doctrine of stare decisis is a key concept in common law systems."},{"term_en":"key concepts of llp","term_te":"","definition_en":"A Limited Liability Partnership (LLP) is a partnership where all partners have limited liability and the business has separate legal entity status.","definition_te":"","example":"Two lawyers forming an LLP to run their law firm, with each having limited personal financial responsibility for the debts of the firm."},{"term_en":"key differences","term_te":"","definition_en":"Key differences refer to the main distinctions between two or more legal concepts, rules, or cases.","definition_te":"","example":"The key difference between murder and manslaughter is the level of intent involved."},{"term_en":"key provisions","term_te":"","definition_en":"Key provisions are the most important parts of a legal document or statute that outline essential rules and requirements.","definition_te":"","example":"In the Indian Constitution, fundamental rights are key provisions that protect citizens' basic freedoms."},{"term_en":"landmark cases to focus on","term_te":"","definition_en":"Landmark cases are significant legal decisions that set important precedents and have lasting influence on the interpretation of laws.","definition_te":"","example":"The case of Kesavananda Bharati v. State of Kerala established the basic structure doctrine in Indian constitutional law."},{"term_en":"legal consequences","term_te":"","definition_en":"Legal consequences refer to the results or effects that follow from an action, decision, or event under the law.","definition_te":"","example":"A person may face imprisonment for committing a crime."},{"term_en":"legal entity","term_te":"","definition_en":"A legal entity is an organization or individual recognized by law as having rights and duties.","definition_te":"","example":"A company registered under the Companies Act, 2013."},{"term_en":"legal ownership","term_te":"","definition_en":"Legal ownership refers to the legally recognized right of an individual or entity to possess, use, and dispose of property.","definition_te":"","example":"A homeowner has legal ownership of their house as evidenced by a deed."},{"term_en":"liability of bailee","term_te":"","definition_en":"The liability of a bailee refers to the legal responsibility they bear towards the bailor for any loss, damage or misuse of goods held in their possession.","definition_te":"","example":"If a warehouse keeper (bailee) allows unauthorized access leading to theft of stored items, they may be liable for compensation."},{"term_en":"lien","term_te":"","definition_en":"A lien is a legal claim or right against property to secure the payment of a debt.","definition_te":"","example":"A mechanic's lien on a car until repair costs are paid."},{"term_en":"lien and stoppage in transit","term_te":"","definition_en":"A lien is a legal claim against property to secure the payment of a debt, while stoppage in transit refers to halting goods during transportation when unpaid debts exist.","definition_te":"","example":"A seller may exercise a lien on delivered goods or stop goods en route if the buyer fails to pay."},{"term_en":"limited liability","term_te":"","definition_en":"Limited liability refers to the legal protection that limits shareholders' or owners' personal financial responsibility to their investment in a company.","definition_te":"","example":"If a corporation goes bankrupt, its directors and shareholders are not personally liable for debts beyond their invested capital."},{"term_en":"limited partnership","term_te":"","definition_en":"A limited partnership is a business structure where there are both general partners with unlimited liability and limited partners whose liability is restricted to their investment.","definition_te":"","example":"A venture capital firm with some investors who only contribute funds but do not manage the company."},{"term_en":"loyalty and confidentiality","term_te":"","definition_en":"Loyalty and confidentiality refer to the duty of an individual, particularly in professional or fiduciary relationships, to act in the best interests of another party and keep sensitive information private.","definition_te":"","example":"A lawyer must maintain client confidence and avoid conflicts of interest that could harm their client's case."},{"term_en":"managing partners","term_te":"","definition_en":"Managing partners are senior members of a partnership who oversee the day-to-day operations and management of the business.","definition_te":"","example":"In a law firm, managing partners may be responsible for client relations and strategic decision-making."},{"term_en":"merchantable quality","term_te":"","definition_en":"Merchantable quality refers to the standard of goods being fit for their ordinary purpose and meeting usual consumer expectations.","definition_te":"","example":"A bag sold in a shop should not have torn seams or weak stitching."},{"term_en":"mohanlal v. shrikrishna (1978)","term_te":"","definition_en":"The case Mohan Lal V. Shrikrisna (1978) is related to the interpretation of Section 304-B IPC, dealing with dowry death.","definition_te":"","example":"It established that a woman's death due to harassment for dowry can be considered under this section even if not directly caused by violence."},{"term_en":"mutual agency","term_te":"","definition_en":"Mutual agency refers to the legal relationship where two or more parties act on each other's behalf, creating obligations and rights between them.","definition_te":"","example":"A partnership agreement where partners can bind each other in business dealings."},{"term_en":"necessity of delivery","term_te":"","definition_en":"Necessity of delivery refers to the legal requirement that certain obligations or rights can only be fulfilled through actual physical transfer of goods.","definition_te":"","example":"In a sale contract, delivering the item is necessary for completing the transaction."},{"term_en":"non-gratuitous bailment","term_te":"","definition_en":"A non-gratuitous bailment is one where the bailee receives compensation or remuneration for taking possession of goods.","definition_te":"","example":"When a warehouse keeper stores someone's货物 in exchange for payment."},{"term_en":"non-managing partners","term_te":"","definition_en":"Non-managing partners are individuals in a partnership who do not participate in the day-to-day management of the business.","definition_te":"","example":"A partner who contributes capital but does not take part in running the firm's operations."},{"term_en":"not compete with the firm","term_te":"","definition_en":"A clause in an employment contract that restricts an employee from working with competitors after leaving the company.","definition_te":"","example":"An ex-employee cannot work for a rival firm within one year of resignation."},{"term_en":"not misuse partnership property","term_te":"","definition_en":"Partners must not use the assets of the firm for personal gain or purposes unrelated to business.","definition_te":"","example":"A partner cannot rent out partnership property for private events without consent."},{"term_en":"obedience to instructions","term_te":"","definition_en":"Obedience to instructions refers to the duty of an individual, particularly in legal or hierarchical contexts, to follow lawful orders given by superiors.","definition_te":"","example":"A soldier must obey a commander's order during military operations unless it violates law or ethics."},{"term_en":"obligations of partners","term_te":"","definition_en":"Obligations of partners refer to the legal duties each partner in a partnership must fulfill towards other partners and third parties.","definition_te":"","example":"A partner must contribute their agreed share of capital and actively participate in business operations as per the agreement."},{"term_en":"on","term_te":"","definition_en":"A preposition indicating location or position in relation to something else.","definition_te":"","example":"The document was signed on the table."},{"term_en":"ordinary partnership","term_te":"","definition_en":"An ordinary partnership is an agreement between two or more persons to carry on a business and share its profits and losses.","definition_te":"","example":"Two friends starting a small retail shop together and splitting the earnings equally."},{"term_en":"other partners","term_te":"","definition_en":"Other partners refer to individuals who are associated with a partner in a firm but do not have the same rights or liabilities.","definition_te":"","example":"A junior lawyer working under a senior partner in a law firm."},{"term_en":"partnership at will","term_te":"","definition_en":"A partnership that can be dissolved by either partner at any time without notice.","definition_te":"","example":"Two friends running a small shop with no fixed term agreement."},{"term_en":"passing of property","term_te":"","definition_en":"Passing of property refers to the legal transfer of ownership or rights in goods from one party to another.","definition_te":"","example":"When a seller delivers goods to a buyer, the passing of property occurs as per the terms agreed upon in the contract."},{"term_en":"patel v. patel (1977)","term_te":"","definition_en":"Patel v. Patel (1977) is a case where the Indian Supreme Court held that a husband cannot claim maintenance from his wife under Section 125 of the Code of Criminal Procedure if she has sufficient means to support herself.","definition_te":"","example":"A husband sought maintenance from his working wife, but the court denied it as she was employed and could sustain her living."},{"term_en":"personal guarantees","term_te":"","definition_en":"A personal guarantee is a legal commitment by an individual to fulfill another party's obligations if they fail to do so.","definition_te":"","example":"Signing a loan agreement promising to pay back the debt if the borrower defaults."},{"term_en":"pledge","term_te":"","definition_en":"A pledge is a form of security interest where personal property is delivered to another party to guarantee the performance of an obligation.","definition_te":"","example":"Pledging a watch to a lender as collateral for a loan."},{"term_en":"possession","term_te":"","definition_en":"Possession refers to the actual control or custody of property by an individual.","definition_te":"","example":"Holding a book in your hands demonstrates possession of that item."},{"term_en":"price","term_te":"","definition_en":"Price is the amount of money paid to acquire goods or services.","definition_te":"","example":"The price of a textbook is ₹500."},{"term_en":"principal-agent relationship","term_te":"","definition_en":"A principal-agent relationship is a legal arrangement where one party (the agent) acts on behalf of another (the principal).","definition_te":"","example":"An employee acting for their employer in business negotiations."},{"term_en":"profit sharing","term_te":"","definition_en":"Profit sharing is an arrangement where employees receive a portion of the company's profits in addition to their regular salary.","definition_te":"","example":"A firm distributes 10% of its annual net profit equally among all full-time employees."},{"term_en":"property","term_te":"","definition_en":"Property refers to any asset or right that can be owned, controlled, and transferred by an individual or entity.","definition_te":"","example":"A house purchased with personal funds is considered property."},{"term_en":"provision","term_te":"","definition_en":"A provision is a specific clause or statement within a legal document that outlines a rule, condition, or requirement.","definition_te":"","example":"A contract may include a provision requiring parties to notify each other of any changes in circumstances."},{"term_en":"r. v. clarke (1971)","term_te":"","definition_en":"R. v. Clarke (1971) is a Canadian criminal case that dealt with the issue of whether a trial judge can properly instruct jurors on reasonable doubt in certain circumstances.","definition_te":"","example":"The court held that overly detailed instructions on reasonable doubt could confuse jurors and potentially violate the accused's right to be tried by a jury."},{"term_en":"reasonable care","term_te":"","definition_en":"Reasonable care refers to the level of caution and prudence that a reasonably careful person would exercise under similar circumstances.","definition_te":"","example":"A driver must maintain reasonable care by obeying traffic signals and avoiding distractions while driving."},{"term_en":"reasonable charges","term_te":"","definition_en":"Reasonable charges refer to fees that are fair and proportionate to the services rendered.","definition_te":"","example":"A lawyer charging $500 for a simple consultation is considered reasonable."},{"term_en":"reclaim goods","term_te":"","definition_en":"Reclaim goods refers to the right of a seller to recover possession of goods from a buyer under certain conditions specified by contract or law.","definition_te":"","example":"A seller may reclaim goods if the buyer fails to make payment as agreed upon in the sales agreement."},{"term_en":"registration","term_te":"","definition_en":"Registration refers to the formal process of recording legal documents or rights with an official authority.","definition_te":"","example":"Registering a property deed with the local land registry office."},{"term_en":"relevant sections","term_te":"","definition_en":"Relevant sections are parts of a statute that apply directly to the case or issue being considered.","definition_te":"","example":"In a theft case, Section 379 of IPC is relevant as it defines the offence of theft."},{"term_en":"remedies for breach","term_te":"","definition_en":"Remedies for breach are legal solutions available to the injured party when another fails to perform their contractual obligations.","definition_te":"","example":"Specific performance may be ordered by a court if monetary damages are insufficient."},{"term_en":"repossess goods","term_te":"","definition_en":"Repossess goods refers to the act of taking back possession of property that was previously owned or leased.","definition_te":"","example":"A landlord repossession a tenant's belongings after eviction due to non-payment of rent."},{"term_en":"representative","term_te":"","definition_en":"A person or entity that acts on behalf of another in legal matters.","definition_te":"","example":"An attorney acting for a client in court."},{"term_en":"repudiate the contract","term_te":"","definition_en":"To formally reject or renounce a合同 under certain conditions.","definition_te":"","example":"A party may repudiate the contract if they refuse to perform their obligations without valid legal grounds."},{"term_en":"requirements","term_te":"","definition_en":"Requirements are the necessary conditions or elements that must be met to establish legal rights, obligations, or validity.","definition_te":"","example":"In contract law, offer and acceptance are requirements for a valid agreement."},{"term_en":"resale","term_te":"","definition_en":"Resale refers to the act of selling goods or property that one has previously purchased.","definition_te":"","example":"A dealer buying cars from manufacturers and then selling them to consumers."},{"term_en":"resell goods","term_te":"","definition_en":"Reselling goods refers to the act of purchasing merchandise with the intention of selling it again at a profit.","definition_te":"","example":"A person buys unused electronics from a retailer and sells them online for a higher price."},{"term_en":"return of goods","term_te":"","definition_en":"Return of goods refers to the process by which a buyer sends back merchandise to a seller, usually due to dissatisfaction or change of mind.","definition_te":"","example":"A customer returns a defective phone to the store for a refund."},{"term_en":"return or disposal","term_te":"","definition_en":"Return or disposal refers to the act of returning property to its rightful owner or getting rid of it in accordance with legal procedures.","definition_te":"","example":"A court may order the return of stolen goods to the victim or their disposal if they are deemed unusable."},{"term_en":"right to","term_te":"","definition_en":"A right to refers to a legal entitlement or claim that an individual or entity has under the law.","definition_te":"","example":"The right to freedom of speech allows individuals to express their opinions without government interference."},{"term_en":"right to access books","term_te":"","definition_en":"The right to access books refers to the legal entitlement of individuals to freely obtain and read written materials without undue restriction.","definition_te":"","example":"A library must allow students to borrow textbooks for their courses."},{"term_en":"right to account","term_te":"","definition_en":"The right to account refers to the legal obligation of an agent or trustee to provide a detailed statement of their dealings with property under someone else's control.","definition_te":"","example":"A guardian must account for all funds managed on behalf of a minor child."},{"term_en":"right to act as agent","term_te":"","definition_en":"The right to act as an agent refers to the authority granted by one party (the principal) to another (the agent) to perform legal acts on their behalf.","definition_te":"","example":"A person authorizing a lawyer to negotiate a contract on their behalf."},{"term_en":"right to be indemnified","term_te":"","definition_en":"The right to be indemnified refers to the legal entitlement of a person to be compensated for any loss or damage suffered due to another party's actions.","definition_te":"","example":"A contractor may have the right to be indemnified by a client if the client's negligence causes delays and additional costs on the project."},{"term_en":"right to participate in management","term_te":"","definition_en":"The right of employees or members to take part in the decision-making processes of an organization.","definition_te":"","example":"Workers' participation in company meetings regarding working conditions."},{"term_en":"right to redeem","term_te":"","definition_en":"The right of a person to repurchase property that they have previously sold under certain conditions.","definition_te":"","example":"A seller may exercise the right to redeem land purchased by another party within a specified period as per legal provisions."},{"term_en":"right to retain goods","term_te":"","definition_en":"The right of a seller to keep possession of goods until payment is received.","definition_te":"","example":"A shopkeeper retains ownership of furniture sold on credit until the buyer pays in full."},{"term_en":"right to sell","term_te":"","definition_en":"The right to sell refers to the legal authority of an owner to transfer ownership of their property to another person.","definition_te":"","example":"A landlord selling a rental apartment to a new buyer."},{"term_en":"rights of debtor","term_te":"","definition_en":"Rights of debtor refer to the legal protections and entitlements that a person who owes money or obligations has under the law.","definition_te":"","example":"A debtor may request reasonable time to repay debts before facing enforcement actions."},{"term_en":"rights of partners","term_te":"","definition_en":"Rights of partners include the right to participate in business, share profits and losses, and act on behalf of the firm.","definition_te":"","example":"A partner can enter into contracts for the partnership without needing approval from other partners."},{"term_en":"rights of pledgee","term_te":"","definition_en":"The rights of a pledgee include the right to retain possession of pledged goods until the debt is repaid.","definition_te":"","example":"A lender may keep a car pawned by a borrower until the loan is fully paid back."},{"term_en":"sale by description","term_te":"","definition_en":"Sale by description refers to the sale of goods where their quality and characteristics are described in detail, rather than being identified by specific items.","definition_te":"","example":"A shop selling \"handmade wooden tables\" with a guarantee that they are crafted from solid wood."},{"term_en":"sale by sample","term_te":"","definition_en":"A sale by sample is a type of contract where the buyer relies on a样品 (sample) provided to represent the quality and characteristics of the goods being sold.","definition_te":"","example":"A seller shows a fabric swatch to a customer before selling bolts of cloth."},{"term_en":"sale of goods","term_te":"","definition_en":"A sale of goods is the transfer of ownership from one person to another in exchange for money.","definition_te":"","example":"Selling a book at a bookstore for ₹200."},{"term_en":"sale of goods act, 1930","term_te":"","definition_en":"The Sale of Goods Act, 1930 is an Indian legislation that governs the sale and purchase of goods in India.","definition_te":"","example":"When a shopkeeper sells a mobile phone to a customer, this transaction falls under the provisions of the Sale of Goods Act, 1930."},{"term_en":"sample","term_te":"","definition_en":"A sample is a representative part of something taken to examine or test the whole.","definition_te":"","example":"A blood sample may be used in forensic analysis to determine identity."},{"term_en":"sections 138–153","term_te":"","definition_en":"Sections 138-153 of the Negotiable Instruments Act, 1881 deal with various aspects related to cheques and their dishonour.","definition_te":"","example":"Section 138 imposes criminal liability on a person who issues a cheque knowing that it would not be honoured by the bank."},{"term_en":"sections 151–153","term_te":"","definition_en":"Sections 151-153 of the Indian Penal Code deal with offences relating to criminal breach of trust and misappropriation.","definition_te":"","example":"A person entrusted with managing another's property embezzles funds for personal use."},{"term_en":"sections 2(26), 27, and 5","term_te":"","definition_en":"Section 2(26) defines 'person' to include companies; section 27 deals with the powers of courts in criminal proceedings; and section 5 outlines the general exceptions to offences.","definition_te":"","example":"A company can be held liable under section 2(26); a court may order an investigation under section 27; self-defence is covered by section 5."},{"term_en":"sections 212–216","term_te":"","definition_en":"Sections 212-216 of the Indian Penal Code deal with offenses related to marriage, including bigamy and solemnization of a second marriage without dissolving the first.","definition_te":"","example":"A person marrying again while their previous spouse is still alive commits an offense under these sections."},{"term_en":"sections 217–218","term_te":"","definition_en":"Sections 217-218 of the Indian Penal Code deal with criminal breach of trust and misappropriation.","definition_te":"","example":"A person entrusted with managing another's property embezzles funds for personal use."},{"term_en":"sections 22–27","term_te":"","definition_en":"Sections 22-27 of the Indian Evidence Act deal with the relevancy of facts in different situations, including statements made by persons under influence and conduct of parties.","definition_te":"","example":"A statement made by a person while drunk may be admissible if it shows their state of mind at the time of an event."},{"term_en":"sections 27 and 5","term_te":"","definition_en":"Section 27 of the Indian Penal Code deals with criminal breach of trust, while section 5 defines general exceptions to offences.","definition_te":"","example":"A person entrusted with property misappropriates it (Section 27), but if they acted under a legal duty, this may be an exception (Section 5)."},{"term_en":"sections 30–32 and 34","term_te":"","definition_en":"Sections 30-32 deal with the general exceptions to criminal liability, while Section 34 deals with common intention among conspirators.","definition_te":"","example":"Under Section 34, if two people plan and commit a theft together, both are equally liable for the crime."},{"term_en":"sections 4–5, 14, 16–20, 44–55","term_te":"","definition_en":"Sections cover various legal procedures including service of process, summons, pleadings, and trial management.","definition_te":"","example":"Section 16 deals with the duty to disclose relevant documents during litigation."},{"term_en":"sections 6 and 28","term_te":"","definition_en":"Section 6 of the Indian Evidence Act deals with the relevancy of facts forming part of same transaction, while section 28 relates to proof of existence of document by reference to other documents.","definition_te":"","example":"Under section 6, evidence of one act in a series may be used for another; under section 28, if an original will is lost, copies can prove its existence."},{"term_en":"sections to memorize","term_te":"","definition_en":"Sections of the legal text that are crucial for understanding and applying laws in practice.","definition_te":"","example":"The Indian Penal Code sections on theft and criminal trespass."},{"term_en":"secured bailment","term_te":"","definition_en":"A secured bailment is a type of bailment where the bailee has possession of the goods and also holds them as security for a debt or obligation.","definition_te":"","example":"When a car is pawned to a lender who keeps it until the loan is repaid."},{"term_en":"security for debt/promise","term_te":"","definition_en":"A security for debt or promise is an assurance given to ensure the performance of a legal obligation.","definition_te":"","example":"Pledge of property by a borrower to secure repayment of a loan."},{"term_en":"security interest","term_te":"","definition_en":"A security interest is a legal claim against personal property to secure the payment of a debt.","definition_te":"","example":"A car loan where the lender has a lien on the vehicle until the loan is repaid."},{"term_en":"seller","term_te":"","definition_en":"A seller is a person or entity that transfers ownership of goods or property to another party in exchange for consideration.","definition_te":"","example":"A shopkeeper selling clothes to a customer."},{"term_en":"separate legal entity","term_te":"","definition_en":"A company is considered a separate legal entity distinct from its shareholders and directors.","definition_te":"","example":"A corporation can own property, enter contracts, and sue or be sued in its own name."},{"term_en":"special agent","term_te":"","definition_en":"A special agent is an individual employed by a government agency to investigate and enforce laws, often dealing with complex or sensitive cases.","definition_te":"","example":"An FBI agent investigating cybercrime is considered a special agent."},{"term_en":"specific","term_te":"","definition_en":"Specific refers to something that is clearly defined or identified rather than general.","definition_te":"","example":"A specific contract term, such as \"payment of $500 on January 1st.\""},{"term_en":"specific goods","term_te":"","definition_en":"Specific goods are identified and agreed upon by the parties at the time of contract formation.","definition_te":"","example":"A particular car with a specific registration number sold under an agreement."},{"term_en":"specific sections","term_te":"","definition_en":"Specific sections refer to particular parts of a statute or legal document that address certain matters in detail.","definition_te":"","example":"Section 302 of the Indian Penal Code specifically deals with punishment for murder."},{"term_en":"stoppage in transit","term_te":"","definition_en":"Stoppage in transit refers to the right of an unpaid seller to stop goods from being delivered to a buyer if they are already on their way.","definition_te":"","example":"A seller can halt delivery of goods shipped by rail if payment has not been received."},{"term_en":"sub-agent","term_te":"","definition_en":"A sub-agent is someone appointed by an agent to perform specific tasks on behalf of the principal.","definition_te":"","example":"An auctioneer hired by a real estate agent to conduct property sales."},{"term_en":"terminate","term_te":"","definition_en":"To bring an end to a legal relationship or obligation.","definition_te":"","example":"A contract may be terminated if one party breaches its terms."},{"term_en":"termination by death or insolvency","term_te":"","definition_en":"Termination by death or insolvency refers to the ending of a contract due to the death of one party or their inability to pay debts because of financial failure.","definition_te":"","example":"A contractor's contract with a client may be terminated if the contractor becomes insolvent and cannot fulfill obligations."},{"term_en":"termination by notice","term_te":"","definition_en":"Termination by notice refers to the legal right of either party in a contract to end the agreement by providing prior written or verbal notification.","definition_te":"","example":"A tenant serving 30 days' notice to their landlord to vacate a rental property."},{"term_en":"termination by performance","term_te":"","definition_en":"Termination by performance occurs when a contract is ended because both parties have fulfilled their obligations under the agreement.","definition_te":"","example":"A contractor completes a building project, and the client pays the agreed amount, ending the contractual relationship."},{"term_en":"termination of agency","term_te":"","definition_en":"Termination of agency refers to the legal end of an agent's authority to act on behalf of their principal.","definition_te":"","example":"A real estate agent’s contract ends when they successfully sell a property as agreed upon in their agreement with the client."},{"term_en":"termination of bailment","term_te":"","definition_en":"Termination of bailment refers to the end of the legal relationship between the bailee and the owner of the goods.","definition_te":"","example":"When a customer returns rented clothing to the shop, the bailment terminates."},{"term_en":"third party","term_te":"","definition_en":"A third party is any person or entity other than the parties directly involved in a legal transaction or dispute.","definition_te":"","example":"In a contract between Alice and Bob, Charlie could be considered a third party if he has an interest in the outcome of their agreement."},{"term_en":"third-party","term_te":"","definition_en":"A third party is any person or entity that is not directly involved in a legal transaction but may be affected by it.","definition_te":"","example":"In a contract between two companies, the government agency regulating the industry is considered a third-party."},{"term_en":"title","term_te":"","definition_en":"Title refers to the legal right or claim of ownership over property.","definition_te":"","example":"A deed serves as proof of title to real estate."},{"term_en":"transfer of interest","term_te":"","definition_en":"Transfer of interest refers to the legal process by which one party conveys their rights or interests in property, contract, or other assets to another party.","definition_te":"","example":"A landlord transferring ownership of a rental property to a new owner through a deed."},{"term_en":"transfer of ownership","term_te":"","definition_en":"Transfer of ownership refers to the legal process by which one party conveys full rights and title to property or goods to another party.","definition_te":"","example":"Selling a car through a signed sale agreement and registration transfer."},{"term_en":"transfer of possession","term_te":"","definition_en":"Transfer of possession refers to the act of moving goods from one person's control to another.","definition_te":"","example":"Selling a book to someone else and handing it over."},{"term_en":"transfer of property","term_te":"","definition_en":"Transfer of property refers to the act of passing ownership or rights in immovable or movable property from one person to another.","definition_te":"","example":"Selling a house to someone else through a registered deed."},{"term_en":"two designated partners","term_te":"","definition_en":"Two designated partners refer to two specific individuals who are legally recognized and appointed within a partnership to manage or represent the firm.","definition_te":"","example":"In a law firm, John and Sarah may be named as the two designated partners responsible for client matters."},{"term_en":"type","term_te":"","definition_en":"A category or classification used to group similar legal concepts, entities, or actions.","definition_te":"","example":"The type of offence in criminal law may be classified as felony or misdemeanor."},{"term_en":"types of agents","term_te":"","definition_en":"Agents can be classified into general agents and special agents based on the scope of their authority.","definition_te":"","example":"A real estate agent is typically a special agent, authorized only to sell specific property."},{"term_en":"types of bailment","term_te":"","definition_en":"Bailment is the temporary transfer of possession of goods from one person to another under an agreement.","definition_te":"","example":"Lending your bike to a friend for a day with permission."},{"term_en":"types of partnerships","term_te":"","definition_en":"A partnership can be general, limited or limited liability depending on the rights and liabilities of partners.","definition_te":"","example":"In a general partnership, all partners share profits and losses equally."},{"term_en":"unascertained goods","term_te":"","definition_en":"Unascertained goods are generic items that have not been specifically identified or separated from other similar goods.","definition_te":"","example":"A bulk shipment of wheat in a warehouse before it is sold to a particular buyer."},{"term_en":"universal agent","term_te":"","definition_en":"A universal agent is someone authorized to act on behalf of another person in all matters.","definition_te":"","example":"An attorney-in-fact appointed under a general power of attorney."},{"term_en":"unpaid seller","term_te":"","definition_en":"An unpaid seller is a person who has not received payment for goods sold.","definition_te":"","example":"A farmer sells crops but does not get the money from the buyer."},{"term_en":"unpaid seller’s remedies","term_te":"","definition_en":"Unpaid seller's remedies refer to the legal rights available to a seller who has not been paid by the buyer under a sales contract.","definition_te":"","example":"A seller may repossess goods if the buyer fails to pay the price."},{"term_en":"use goods","term_te":"","definition_en":"Use goods refer to items that are consumed or used up in the process of production.","definition_te":"","example":"Raw materials like coal and oil used in manufacturing."},{"term_en":"voluntary","term_te":"","definition_en":"An action performed by someone without any external compulsion or coercion.","definition_te":"","example":"Donating to charity is an act of voluntary contribution."},{"term_en":"warranty","term_te":"","definition_en":"A warranty is a statement or promise made by one party to another in a contract, which assures the truth of certain facts and may give rise to liability if false.","definition_te":"","example":"A seller warranties that a car has no prior accidents."},{"term_en":"winding up","term_te":"","definition_en":"Winding up refers to the legal process of closing down a company and distributing its assets among creditors and shareholders.","definition_te":"","example":"A court may order winding up if a company is insolvent and unable to pay debts."},{"term_en":"| designated partners |","term_te":"","definition_en":"Designated partners are specific individuals or entities within a partnership that have been assigned particular roles, responsibilities, or authority by the partnership agreement.","definition_te":"","example":"In an LLP, designated partners may be responsible for managing day-to-day operations while others act as silent investors."},{"term_en":"| dissolution |","term_te":"","definition_en":"Dissolution refers to the legal process of ending a partnership or company by winding up its affairs and distributing assets.","definition_te":"","example":"A partnership may be dissolved if all partners agree to terminate their business operations."},{"term_en":"| liability of partners |","term_te":"","definition_en":"Liability of partners refers to the legal responsibility each partner in a partnership firm has towards the debts and obligations of the business.","definition_te":"","example":"If one partner incurs debt for the business, all other partners are personally liable for repaying it."},{"term_en":"| minimum partners |","term_te":"","definition_en":"The smallest number of people required to form a particular type of business entity, such as a partnership or company.","definition_te":"","example":"A minimum of two partners is required to establish a general partnership under most legal systems."},{"term_en":"| registration of llp |","term_te":"","definition_en":"Registration of LLP refers to the legal process by which a Limited Liability Partnership is officially registered with the Registrar of Companies under the LLP Act, 2008.","definition_te":"","example":"A group of professionals forming an LLP must file Form INC-3 and other required documents with ROC for registration."},{"term_en":"| winding up |","term_te":"","definition_en":"Winding up refers to the legal process of closing down a company and settling its debts.","definition_te":"","example":"A court may order winding up if a company is insolvent and unable to pay its creditors."}],"papers":[]};window.SP_LOADED&&SP_LOADED("sem2_contract2");